export type PublicProjectionSelection={campaignId?:string;sellerId?:string};
export type PublicProjectionState={revision:number;campaigns:Record<string,CampaignRecord>;products:DatabaseSchema['products'];productVersions:DatabaseSchema['productVersions'];licenseVersions:DatabaseSchema['licenseVersions'];rights:DatabaseSchema['rights'];users:Record<string,{id:string;sellerProfile?:UserRecord['sellerProfile'];payoutCredentialLinked:boolean}>};
const publicCampaignFields=['id','sellerId','onchainCampaignId','chainId','hubAddress','projectionOrigin','productSnapshot','title','description','category','thumbnailUrl','sellerPayoutWallet','status','visibility','metric','currentUnlockedTier','maxPerAccount','inventoryLimit','durationSeconds','deliverySlaSeconds','earlyRebateEnabled','earlySlotsCount','earlyRebateAmount','earlyRebateBps','platformFeeBps','termsHash','startTime','endTime','finalizedAt','finalClearingPrice','totalBuyerCount','totalUnitsCommitted','totalGrossCommitted','deliveryMethod','txHash','protocolVersion','tiers','termsPolicyReviewRequired','amendments'] as const;
/** SQL constructs only declared public leaves and graph bindings before any JSON decoding. */
const publicProjection=(fields:readonly string[],column='record_json'):string=>{
 const scalar=(f:string,c:string)=>"CASE WHEN json_type("+c+",'$."+f+"') IN ('object','array') THEN json_object('__invalidPublic',json('true')) WHEN json_type("+c+",'$."+f+"') IN ('true','false') THEN json(json_type("+c+",'$."+f+"')) ELSE json_extract("+c+",'$."+f+"') END";
 const structured=(f:string,keys:readonly string[])=>"json(CASE WHEN json_type("+column+",'$."+f+"')='object' THEN "+publicProjection(keys,"json_extract("+column+",'$."+f+"')")+" END)";
 const nested=(f:string,keys:readonly string[])=>"json(CASE WHEN json_type("+column+",'$."+f+"')='array' THEN (SELECT json_group_array(json("+publicProjection(keys,'value')+")) FROM json_each("+column+",'$."+f+"')) END)";
 const strings=(f:string)=>"json(CASE WHEN json_type("+column+",'$."+f+"')='array' AND NOT EXISTS(SELECT 1 FROM json_each("+column+",'$."+f+"') WHERE type<>'text') THEN json_extract("+column+",'$."+f+"') END)";
 const object='json_object('+fields.map(f=>"'"+f+"',"+(f==='provider'?structured(f,['schema','campaignId','licenseVersionId','subscriptionId','endpoint','subscriptionFingerprint','chainId','hubAddress','byteLength','expiresAt','commandId','requestSha256','responseSha256']):f==='replacementFor'?structured(f,['campaignId','onchainCampaignId','chainId','hubAddress','creationTermsHash','sourceProtocolVersion']):f==='productSnapshot'?structured(f,['schema','productId','productVersionId','licenseVersionId','productContentHash','licenseContentHash','rightsId','rightsApprovedAt','rightsValidUntil']):f==='sellerProfile'?structured(f,['displayName','bio','payoutWallet','verifiedSellerBadge']):f==='tiers'?nested(f,['threshold','price']):f==='amendments'?nested(f,['id','timestamp','note','hash']):f==='media'?nested(f,['url','alt']):['requirements','regions'].includes(f)?strings(f):scalar(f,column))).join(',')+')';
 return 'json_remove('+object+fields.map(f=>",CASE WHEN json_type("+column+",'$."+f+"') IS NULL THEN '$."+f+"' ELSE '$.__public_absent_placeholder' END").join('')+')';
};

const operationTrackingProjection=(tree:PublicTree=operationPublicTree,column='record_json'):string=>{
 const nested=Object.entries(tree.objects??{}).map(([field,child])=>[field,"json(CASE WHEN json_type("+column+",'$."+field+"')='object' THEN "+operationTrackingProjection(child,"json_extract("+column+",'$."+field+"')")+" ELSE json_object('__invalidPublic',json('true')) END)"]);
 const arrays=Object.entries(tree.arrays??{}).map(([field,child])=>[field,"json(CASE WHEN json_type("+column+",'$."+field+"')='array' AND json_array_length("+column+",'$."+field+"')<=1000 THEN (SELECT json_group_array(json("+operationTrackingProjection(child,'op_item.value')+")) FROM json_each("+column+",'$."+field+"') AS op_item) ELSE json_object('__invalidPublic',json('true')) END)"]);
 const entries=[...nested,...arrays];let value=publicProjection(tree.scalars,column);
 if(entries.length)value='json_set('+value+entries.map(([f,sql])=>",'$."+f+"',"+sql).join('')+')';
 return entries.length?'json_remove('+value+entries.map(([f])=>",CASE WHEN json_type("+column+",'$."+f+"') IS NULL THEN '$."+f+"' ELSE '$.__public_absent_placeholder' END").join('')+')':value;
};

