const productProjection=(fields:readonly string[])=>{
  const scalar=(field:string)=>"CASE WHEN json_type(record_json,'$."+field+"') IN ('object','array') THEN NULL WHEN json_type(record_json,'$."+field+"') IN ('true','false') THEN json(json_type(record_json,'$."+field+"')) ELSE json_extract(record_json,'$."+field+"') END";
  const strings=(field:string)=>"json(CASE WHEN json_type(record_json,'$."+field+"')='array' AND NOT EXISTS(SELECT 1 FROM json_each(record_json,'$."+field+"') WHERE type<>'text') THEN json_extract(record_json,'$."+field+"') END)";
  const nested=(field:string,fields:readonly string[])=>"json(CASE WHEN json_type(record_json,'$."+field+"')='array' THEN (SELECT json_group_array(json_object("+fields.map(f=>"'"+f+"',CASE WHEN json_type(value,'$."+f+"') IN ('object','array') THEN NULL ELSE json_extract(value,'$."+f+"') END").join(',')+")) FROM json_each(record_json,'$."+field+"')) END)";
  const nullable=(field:string)=>"CASE WHEN json_type(record_json,'$."+field+"')='null' THEN NULL WHEN json_type(record_json,'$."+field+"')='integer' THEN json_extract(record_json,'$."+field+"') ELSE 'UNVERIFIED_MISSING_OR_INVALID' END";
  const optional=(field:string,type:string)=>"CASE WHEN json_type(record_json,'$."+field+"') IS NULL OR json_type(record_json,'$."+field+"')='null' THEN NULL WHEN json_type(record_json,'$."+field+"')='"+type+"' THEN json_extract(record_json,'$."+field+"') ELSE json('false') END";
  return 'json_object('+fields.map(f=>"'"+f+"',"+(f==='media'?nested(f,['url','alt']):f==='decisions'?nested(f,['actorId','decision','reason','timestamp']):['requirements','regions','evidenceRefs'].includes(f)?strings(f):f==='transferable'?"json(CASE json_type(record_json,'$.transferable') WHEN 'true' THEN 'true' WHEN 'false' THEN 'false' END)":['durationDays','activationWindowDays'].includes(f)?nullable(f):f==='validUntil'?optional(f,'integer'):f==='activeVersionId'?optional(f,'text'):scalar(f))).join(',')+')';
};

