  constructor(private readonly sqlite: DatabaseSync) {
    sqlite.exec(`
      CREATE TABLE IF NOT EXISTS storage_revision (
        id INTEGER PRIMARY KEY CHECK(id = 1), revision INTEGER NOT NULL, format_version INTEGER NOT NULL
      );
      CREATE TABLE IF NOT EXISTS domain_records (
        collection TEXT NOT NULL, record_key TEXT NOT NULL,
        record_json TEXT NOT NULL CHECK(json_valid(record_json)),
        PRIMARY KEY(collection, record_key)
      ) WITHOUT ROWID;
      CREATE TABLE IF NOT EXISTS legacy_snapshot_guard(id INTEGER PRIMARY KEY CHECK(id = 1), snapshot_hash TEXT NOT NULL);
      CREATE UNIQUE INDEX IF NOT EXISTS domain_signer_active_key ON domain_records(json_extract(record_json,'$.chainId'),lower(json_extract(record_json,'$.principal'))) WHERE collection='signerReservations' AND json_extract(record_json,'$.phase')='ACTIVE';
      CREATE UNIQUE INDEX IF NOT EXISTS domain_bridge_active_sender ON domain_records(lower(json_extract(record_json,'$.scope.sender'))) WHERE collection='bridgeTransfers' AND json_extract(record_json,'$.phase')='RESERVED';
      CREATE UNIQUE INDEX IF NOT EXISTS domain_bridge_active_recipient ON domain_records(lower(json_extract(record_json,'$.scope.recipient'))) WHERE collection='bridgeTransfers' AND json_extract(record_json,'$.phase')='RESERVED';
      CREATE UNIQUE INDEX IF NOT EXISTS domain_campaign_binding ON domain_records(
        COALESCE(json_extract(record_json,'$.chainId'),'UNSCOPED'),
        lower(COALESCE(json_extract(record_json,'$.hubAddress'),'UNSCOPED')),
        json_extract(record_json,'$.onchainCampaignId')
      ) WHERE collection='campaigns' AND json_extract(record_json,'$.onchainCampaignId') IS NOT NULL;
      CREATE UNIQUE INDEX IF NOT EXISTS domain_order_binding ON domain_records(
        json_extract(record_json,'$.chainId'),lower(json_extract(record_json,'$.hubAddress')),
        json_extract(record_json,'$.onchainOrderId')
      ) WHERE collection='orders' AND json_extract(record_json,'$.chainId') IS NOT NULL AND json_extract(record_json,'$.hubAddress') IS NOT NULL;
      CREATE UNIQUE INDEX IF NOT EXISTS domain_campaign_identity_owner ON domain_records(
        json_extract(record_json,'$.accountId'),json_extract(record_json,'$.campaignId')
      ) WHERE collection='campaignIdentities';
      CREATE UNIQUE INDEX IF NOT EXISTS domain_campaign_identity_hash ON domain_records(
        json_extract(record_json,'$.campaignId'),lower(json_extract(record_json,'$.identity'))
      ) WHERE collection='campaignIdentities';
      CREATE UNIQUE INDEX IF NOT EXISTS domain_event_identity ON domain_records(
        json_extract(record_json,'$.chainId'),lower(json_extract(record_json,'$.contractAddress')),
        lower(json_extract(record_json,'$.txHash')),json_extract(record_json,'$.logIndex')
      ) WHERE collection='eventJournal';
      CREATE UNIQUE INDEX IF NOT EXISTS domain_operation_key ON domain_records(
        json_extract(record_json,'$.userId'),json_extract(record_json,'$.idempotencyKey')
      ) WHERE collection='operations';
      CREATE UNIQUE INDEX IF NOT EXISTS domain_webhook_event ON domain_records(json_extract(record_json,'$.sellerId'),json_extract(record_json,'$.eventId')) WHERE collection='webhookQueue' AND json_extract(record_json,'$.eventId') IS NOT NULL AND json_extract(record_json,'$.status') <> 'DLQ';
      CREATE UNIQUE INDEX IF NOT EXISTS domain_license_fingerprint ON domain_records(json_extract(record_json,'$.keyFingerprint')) WHERE collection='licenseInventory';
      CREATE UNIQUE INDEX IF NOT EXISTS domain_grant_unit ON domain_records(json_extract(record_json,'$.orderId'),json_extract(record_json,'$.unitIndex')) WHERE collection='resourceGrants';
      CREATE INDEX IF NOT EXISTS domain_auth_session_owner ON domain_records(json_extract(record_json,'$.userId')) WHERE collection='authSessions';
      CREATE INDEX IF NOT EXISTS domain_seller_follow_owner ON domain_records(json_extract(record_json,'$.userId')) WHERE collection='sellerFollows';
      CREATE INDEX IF NOT EXISTS domain_support_owner ON domain_records(json_extract(record_json,'$.accountId'),json_extract(record_json,'$.sellerId')) WHERE collection='supportTickets';
      CREATE UNIQUE INDEX IF NOT EXISTS domain_support_order ON domain_records(json_extract(record_json,'$.orderId')) WHERE collection='supportTickets' AND json_extract(record_json,'$.kind')='ORDER';
      CREATE INDEX IF NOT EXISTS domain_support_message_ticket ON domain_records(json_extract(record_json,'$.ticketId')) WHERE collection='supportTicketMessages';
      CREATE INDEX IF NOT EXISTS domain_support_attachment_ticket ON domain_records(json_extract(record_json,'$.ticketId')) WHERE collection='supportAttachments';
    `);
  }

