        const active="json_extract(record_json,'$.status') IN ("+pending.map(()=>'?').join(',')+")",valid="json_type(record_json,'$.nextAttemptAt')='integer' AND json_extract(record_json,'$.nextAttemptAt') BETWEEN 0 AND 8640000000000000";
